// Calculate cost for each axis
for (int axis = 0; axis < 3; axis++) {
    const real3<T>& min = (axis == 0) ? real3<T>(bmin.x, bmin.y, bmin.z) :
                          (axis == 1) ? real3<T>(bmin.x, bmin.y, bmax.z) :
                          real3<T>(bmin.x, bmax.y, bmin.z);
    const real3<T>& max = (axis == 0) ? real3<T>(bmax.x, bmin.y, bmin.z) :
                          (axis == 1) ? real3<T>(bmax.x, bmax.y, bmin.z) :
                          real3<T>(bmin.x, bmax.y, bmax.z);

    // Calculate surface area
    real3<T> size = bmax - bmin;
    real<T> surface_area = 2.0 * (size.x * size.y + size.y * size.z + size.z * size.x);

    // Calculate cost for each bin
    real<T> total_cost = std::numeric_limits<real<T>>::max();
    real<T> best_cost = std::numeric_limits<real<T>>::max();
    int best_bin = -1;

    // Find the best split position
    for (int bin = 0; bin < bins->num_bins[axis]; bin++) {
        real<T> bin_cost = 0.0;
        real<T> bin_surface = 0.0;

        // Calculate cost for this bin
        for (int i = 0; i < bins->num_prims[axis][bin]; i++) {
            const auto& prim = bins->prims[axis][bin][i];
            real3<T> prim_size = prim.max - prim.min;
            bin_surface += 2.0 * (prim_size.x * prim_size.y + prim_size.y * prim_size.z + prim_size.z * prim_size.x);
        }

        // Calculate cost for left and right parts
        real<T> left_cost = bin_surface * (real<T)bin / bins->num_bins[axis];
        real<T> right_cost = bin_surface * (real<T)(bins->num_bins[axis] - bin) / bins->num_bins[axis];

        // Calculate total cost for this split
        real<T> current_cost = left_cost + right_cost + surface_area * (left_cost + right_cost) / surface_area;

        if (current_cost < best_cost) {
            best_cost = current_cost;
            best_bin = bin;
        }
    }

    // Calculate the actual cut position
    real<T> cut_pos_val = bmin[axis] + (real<T)best_bin / bins->num_bins[axis] * (bmax[axis] - bmin[axis]);
    cut_pos[axis] = cut_pos_val;

    // Store the cost for this axis
    if (best_cost < total_cost) {
        total_cost = best_cost;
        *minCostAxis = axis;
    }
}

return true;

